// 把门禁打成单文件 ESM：yaml 等依赖内联，运行时只需要 Node，不需要 node_modules / tsx。
// 产物放在仓库的 assets/verify.mjs，随 TS 核心与桌面端分发，CI 会检查它与源码一致。
import { build } from 'esbuild'

await build({
  entryPoints: ['verify.ts'],
  outfile: '../assets/verify.mjs',
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node22',
  legalComments: 'none',
  banner: {
    // yaml 走的是 CommonJS 构建，会 require('process') 等内置模块；ESM 产物里得补一个真正的 require
    js: [
      '// GENERATED by verify/build.mjs from verify/*.ts — do not edit.',
      'import { createRequire as __wwkCreateRequire } from "node:module";',
      'const require = __wwkCreateRequire(import.meta.url);',
    ].join('\n'),
  },
  logLevel: 'warning',
})
